"use client";

import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { glowDestructive, glowPrimary } from "./_shared";

/** A disabled lit button keeps a warm paper fill, so its shape stays in place. */
const litDisabled = "disabled:bg-secondary data-[disabled]:bg-secondary";

/**
 * Firefly IconButton: a single glyph in the same materials as the Button.
 *
 * It is round by default, like every Firefly pill. The square shape keeps a
 * corner that grows with the button, so a small one never reads as a
 * circle. The default is a warm paper disc; `primary` is the lit pill, kept
 * for the one action a screen offers; ghost is the quiet choice for
 * toolbars and rows.
 */
const iconButtonVariants = cva(
  [
    "relative inline-flex shrink-0 select-none items-center justify-center",
    "transition-[background-color,color,border-color,scale] duration-fast ease-out",
    "active:scale-95",
    "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
    "disabled:pointer-events-none disabled:bg-none disabled:text-(--foreground-disabled) disabled:shadow-none disabled:before:hidden",
    "data-[disabled]:pointer-events-none data-[disabled]:bg-none data-[disabled]:text-(--foreground-disabled) data-[disabled]:shadow-none data-[disabled]:before:hidden",
    "[&_svg]:pointer-events-none [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        default:
          "bg-secondary text-secondary-foreground hover:bg-(--surface-3) data-[disabled]:bg-secondary",
        primary: `${glowPrimary} ${litDisabled}`,
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-(--surface-3) data-[disabled]:bg-secondary",
        ghost: "bg-transparent text-foreground hover:bg-secondary",
        destructive: `${glowDestructive} ${litDisabled}`,
        outline:
          "border border-(--line-strong) bg-transparent text-foreground hover:bg-muted data-[disabled]:border-border",
      },
      size: {
        xs: "size-7 rounded-md [&_svg]:size-3.5",
        sm: "size-8 rounded-md [&_svg]:size-4",
        default: "size-10 rounded-lg [&_svg]:size-5",
        lg: "size-12 rounded-xl [&_svg]:size-6",
        xl: "size-14 rounded-xl [&_svg]:size-6",
      },
      corners: {
        square: "",
        circle: "rounded-full",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
      corners: "circle",
    },
  },
);

/** Props for the IconButton. Give it an `aria-label`, since the glyph carries no text. */
export interface IconButtonProps
  extends
    Omit<ButtonPrimitive.Props, "className">,
    VariantProps<typeof iconButtonVariants> {
  className?: string;
}

const IconButton = React.forwardRef<HTMLButtonElement, IconButtonProps>(
  ({ className, variant, size, corners, ...props }, ref) => (
    <ButtonPrimitive
      ref={ref}
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant, size, corners, className }))}
      {...props}
    />
  ),
);
IconButton.displayName = "IconButton";

export { IconButton, iconButtonVariants };
